from importlib.metadata import entry_points

def load_builders(group: str = "myapp.shapes") -> dict[str, Callable]:
    builders: dict[str, Callable] = {}
    for ep in entry_points(group=group):          # Python 3.10+ selectable API
        try:
            builders[ep.name] = ep.load()
        except Exception:                          # one broken plugin must not sink discovery
            logging.warning("skipping %s", ep.name, exc_info=True)
    return builders
